select t.refund_id,t.refund_id refundId,t.pay_id,t.pay_id payId,t.refund_fee,t.refund_fee
refundFee,t.busi_id,t.busi_id busiId,t.community_id,t.community_id communityId,t.state,t.message,t.create_time createTime,
t.status_cd,t.status_cd statusCd,t.refund_user_id,t.refund_user_id refundUserId
from online_pay_refund t
where 1 =1

    and t.refund_id= #{refundId}


    and t.pay_id= #{payId}


    and t.refund_fee= #{refundFee}


    and t.busi_id= #{busiId}


    and t.community_id= #{communityId}


    and t.state= #{state}


    and t.message= #{message}


    and t.status_cd= #{statusCd}


    and t.refund_user_id= #{refundUserId}

order by t.create_time desc

    limit #{page}, #{row}

